/**
 * Tips: one sentence or two each about something Hive can do, shown one a day in a card when Hive starts, at the
 * moment they matter (contextual), and all together in Help → Tips…. Adding a tip is adding an entry to TIP_ENTRIES, in
 * id order, with an `order` for where it's shown.
 *
 * A tip's title and text are messages (#767), shown in the user's language. Its text may name a shortcut as {key},
 * with the command in `key`: shown as the command's current shortcut (the user's own, if changed). Without one it is
 * left out at the end of the text, and named by the command's label elsewhere. `docs` is a heading of the user guide
 * that Learn more opens (English: D2 gives the guide's headings anchors).
 */
import { msg, type Msg } from './i18n/msg'
import { cardCostLine, emptyPart } from './cardCosts'
import { formatDate, formatTime } from './dates'
import { gitStatusText, type GitRepoSummary } from './gitRepo'
import { AGENT_LIMIT_DEFAULT, AGENT_LIMIT_MAX, DEFAULT_SETTINGS } from './defaults'
import { OVERDUE_MINUTES } from './deliveries'
import { LOOP_ROUNDS, LOOP_WAIT_HOURS } from './lanes'
import { RECENT_KEPT, RECENT_RUNS } from './progress'
import { CLEANUP_AGE_MS } from './sessionCleanup'

/** A tip's group: an id, which Help → Tips names with TIP_GROUP_TEXT. */
export type TipGroup = 'Sessions' | 'Agents' | 'Board' | 'Assistant' | 'Files' | 'Shortcuts'
export const TIP_GROUPS: TipGroup[] = ['Sessions', 'Agents', 'Board', 'Assistant', 'Files', 'Shortcuts'] // i18n-ignore: group ids (TIP_GROUP_TEXT names them)

/** Each group's heading in Help → Tips. */
export const TIP_GROUP_TEXT: Record<TipGroup, Msg> = {
  Sessions: msg({ id: 'tips.group.sessions', defaultMessage: 'Sessions', description: 'A heading of Help → Tips: tips about sessions.' }),
  Agents: msg({ id: 'tips.group.agents', defaultMessage: 'Agents', description: 'A heading of Help → Tips: tips about agents.' }),
  Board: msg({ id: 'tips.group.board', defaultMessage: 'Board', description: 'A heading of Help → Tips: tips about the task board.' }),
  Assistant: msg({ id: 'tips.group.assistant', defaultMessage: 'Assistant', description: 'A heading of Help → Tips: tips about the Hive Assistant.' }),
  Files: msg({ id: 'tips.group.files', defaultMessage: 'Files', description: "A heading of Help → Tips: tips about files and a project's git." }),
  Shortcuts: msg({ id: 'tips.group.shortcuts', defaultMessage: 'Shortcuts', description: 'A heading of Help → Tips: shortcuts and other ways to get around Hive.' })
}

export interface Tip {
  id: string
  group: TipGroup
  /**
   * Where it comes in the tip of the day's rounds, Help → Tips and "Tip n of N": lowest first, unique. Give a new tip a
   * free number in the gap where it belongs (they go up in tens to leave room).
   */
  order: number
  /** Its words: messages (#767, shown with tr() in the window); plain text only in tests. */
  title: string | Msg
  text: string | Msg
  /**
   * The numbers and examples its title and text show, as values (#911): formatted as they are shown, in the language
   * shown, rather than written into the words. Read when shown.
   */
  values?: () => Record<string, string | number>
  /** The command whose shortcut {key} in its text shows. */
  key?: string
  /** A heading of the user guide (Learn more). */
  docs?: string
  /** A command Try it runs. */
  command?: string
  /** Not shown by itself once the user has run any of these commands (they know it already). Default: `command`. */
  knownBy?: string[]
}

/** Moments a tip is worth showing at, once each. */
export type TipMoment = 'transcript-long' | 'compact-suggested' | 'second-agent' | 'image-pasted'

/** The tip for each moment. */
export const TIP_MOMENTS: Record<TipMoment, string> = {
  'transcript-long': 'handover-self',
  'compact-suggested': 'compact-focus',
  'second-agent': 'agent-layouts',
  'image-pasted': 'images-tab'
}

/** Main's MAX_CHANGE_BATCH (tasks.ts) and MAX_ACTIONS_PER_TURN (assistantControl.ts), which shared code can't import. */
const ASSISTANT_LIMITS = { cards: 100, changes: 30 }
const HOUR_MS = 3600_000
const DAY_MS = 24 * HOUR_MS
/** The date and time the date-format tip shows in the formats chosen: 4 October 2026, 14:05. */
const EXAMPLE_TIME = new Date(2026, 9, 4, 14, 5)
/** The git the Git tab's tip shows in the status bar's words: main, tracking origin/main, 2 commits ahead. */
const EXAMPLE_GIT: GitRepoSummary = { isRepo: true, branch: 'main', head: null, state: null, upstream: { name: 'origin/main', remote: 'origin', ahead: 2, behind: 0 }, remotes: ['origin'], fetchedAt: null }

